import base64
import hashlib
import json
from pathlib import Path
import re
import sys


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def verify(root, app):
    web = ['css/party.css'] + [f'js/{n}.js' for n in
           ['modes', 'play', 'qr', 'session', 'transport', 'ui', 'views']] + ['play.html']
    web = sorted(web)
    packs = ['feud.json', 'who_am_i.json']
    receipts = {}
    for name, paths, origin in [('PartyWeb', web, root/'party/web'),
                                ('PartyContent', packs, root/'party/content')]:
        generated = root/'majlis-ios'/name
        bundled = app/name
        assert generated.is_dir() and bundled.is_dir(), f'missing {name}'
        for directory in (generated, bundled):
            observed = sorted(str(p.relative_to(directory)) for p in directory.rglob('*')
                              if p.is_file() and p.name != 'MANIFEST.txt')
            assert observed == paths, f'{directory}: membership mismatch'
        if name == 'PartyWeb':
            manifest = [line for line in (generated/'MANIFEST.txt').read_text().splitlines()
                        if line and not line.startswith(('Generated by ', 'Files copied '))]
            assert sorted(manifest) == paths, 'PartyWeb manifest paths mismatch'
        else:
            entries = re.findall(r'^([a-f0-9]{64})  (.+)$',
                                 (generated/'MANIFEST.txt').read_text(), re.M)
            assert len(entries) == 2 and sorted(p for _, p in entries) == paths
            for digest, path in entries:
                assert digest == sha(origin/path), f'content source hash: {path}'
        assert (bundled/'MANIFEST.txt').read_bytes() == (generated/'MANIFEST.txt').read_bytes()
        for path in paths:
            expected = sha(origin/path)
            assert sha(generated/path) == expected, f'generated drift: {name}/{path}'
            assert sha(bundled/path) == expected, f'bundle drift: {name}/{path}'
            receipts[f'{name}/{path}'] = expected
    embedded = (root/'party/native/gen/EmbeddedSources.swift').read_text()
    for source in ['party/core/unicode13.generated.js', 'party/core/majlis-core.js',
                   'party/native/majlis-native.js']:
        expected = sha(root/source)
        assert f'// {source} sha256 {expected}' in embedded, f'embedded receipt: {source}'
        match = re.search(r'EngineSource\(name: "' + re.escape(Path(source).name) +
                          r'", text: decode\("([A-Za-z0-9+/=]+)"\)\)', embedded)
        assert match and base64.b64decode(match[1], validate=True) == (root/source).read_bytes()
        receipts[source] = expected
    return receipts


if __name__ == '__main__':
    result = verify(Path(sys.argv[1]).resolve(), Path(sys.argv[2]).resolve())
    print(json.dumps(result, indent=2, sort_keys=True))
